// MIL_STD_1553_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module MIL_STD_1553_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_cfg_bc,
  input logic  c_cfg_bcast_en,
  input logic [4:0] c_cfg_rt_addr,
  input logic  c_cfg_sr,
  input logic  c_cfg_busy,
  input logic  c_cfg_ssf,
  input logic  c_cfg_tf,
  input logic [7:0] c_cfg_half,
  input logic [7:0] c_cfg_resp_timeout,
  input logic [15:0] c_cfg_vector,
  input logic [15:0] c_cfg_bit_word,
  input logic [15:0] c_bc_cmd1,
  input logic [15:0] c_bc_cmd2,
  input logic [2:0] c_bc_type,
  input logic  c_bc_bus,
  input logic [10:0] c_host_addr,
  input logic [15:0] c_host_wdata,
  input logic  c_bc_start,
  input logic  c_host_wr,
  input logic  c_host_rd,
  input logic [15:0] c_host_rdata,
  input logic  c_bc_busy,
  input logic  c_bc_err_noresp,
  input logic  c_bc_err_addr,
  input logic  c_bc_err_word,
  input logic  c_bc_err_wc,
  input logic [5:0] c_bc_cnt,
  input logic [15:0] c_bc_stat1,
  input logic [15:0] c_bc_stat2,
  input logic [1:0] c_rt_tx_shut,
  input logic  c_rt_tf_inh,
  input logic [15:0] c_mc_data,
  input logic [15:0] c_rt_msg_cmd,
  input logic  c_rt_msg_bus,
  input logic  c_rt_msg_err,
  input logic [2:0] c_rt_msg_why,
  input logic  c_rt_msg_bcast,
  input logic [5:0] c_rt_msg_cnt,
  input logic  c_rt_msg,
  input logic  c_bc_done,
  input logic  c_mc_sync,
  input logic  c_mc_selftest,
  input logic  c_mc_reset,
  input logic  c_mc_sync_data
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 18;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:17];          // model of every stored word
  logic [6:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_RT_MSG;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_bc_done) m_set[0] = 1'b1;
    if (c_mc_sync) m_set[1] = 1'b1;
    if (c_mc_selftest) m_set[2] = 1'b1;
    if (c_mc_reset) m_set[3] = 1'b1;
    if (c_mc_sync_data) m_set[4] = 1'b1;
    if (c_rt_msg && !m_state_RT_MSG) m_set[5] = 1'b1;
    if (c_rt_msg && m_state_RT_MSG && (m_rd && m_map && m_idx == 17)) m_set[5] = 1'b1;
    if (c_rt_msg && m_state_RT_MSG && !(m_rd && m_map && m_idx == 17)) m_set[6] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h2;
      m_w[6] <= 32'h1C19;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_RT_MSG <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 12) ? PWDATA & m_be & 32'h7 : 0;
      if (c_rt_msg && (!m_state_RT_MSG || (m_rd && m_map && m_idx == 17))) begin
        m_w[17] <= (32'(c_rt_msg_cmd[15:0]) << 0) | (32'(c_rt_msg_bus) << 16) | (32'(c_rt_msg_err) << 17) | (32'(c_rt_msg_why[2:0]) << 18) | (32'(c_rt_msg_bcast) << 21) | (32'(c_rt_msg_cnt[5:0]) << 22);
        m_state_RT_MSG <= 1;
      end else if ((m_rd && m_map && m_idx == 17)) m_state_RT_MSG <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h15530100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RT_MSG});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return 0;
      13: return (32'(c_host_rdata) << 0);
      14: return (32'(c_bc_busy) << 0) | (32'(c_bc_err_noresp) << 1) | (32'(c_bc_err_addr) << 2) | (32'(c_bc_err_word) << 3) | (32'(c_bc_err_wc) << 4) | (32'(c_bc_cnt) << 5);
      15: return (32'(c_bc_stat1) << 0) | (32'(c_bc_stat2) << 16);
      16: return (32'(c_rt_tx_shut) << 0) | (32'(c_rt_tf_inh) << 2) | (32'(c_mc_data) << 3);
      17: return m_w[17];
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][6:0] & m_w[2][6:0]))
  `SVA_INV(a_core_cfg_bc, c_cfg_bc == m_w[5][0:0])
  `SVA_INV(a_core_cfg_bcast_en, c_cfg_bcast_en == m_w[5][1:1])
  `SVA_INV(a_core_cfg_rt_addr, c_cfg_rt_addr == m_w[5][6:2])
  `SVA_INV(a_core_cfg_sr, c_cfg_sr == m_w[5][7:7])
  `SVA_INV(a_core_cfg_busy, c_cfg_busy == m_w[5][8:8])
  `SVA_INV(a_core_cfg_ssf, c_cfg_ssf == m_w[5][9:9])
  `SVA_INV(a_core_cfg_tf, c_cfg_tf == m_w[5][10:10])
  `SVA_INV(a_core_cfg_half, c_cfg_half == m_w[6][7:0])
  `SVA_INV(a_core_cfg_resp_timeout, c_cfg_resp_timeout == m_w[6][15:8])
  `SVA_INV(a_core_cfg_vector, c_cfg_vector == m_w[7][15:0])
  `SVA_INV(a_core_cfg_bit_word, c_cfg_bit_word == m_w[7][31:16])
  `SVA_INV(a_core_bc_cmd1, c_bc_cmd1 == m_w[8][15:0])
  `SVA_INV(a_core_bc_cmd2, c_bc_cmd2 == m_w[8][31:16])
  `SVA_INV(a_core_bc_type, c_bc_type == m_w[9][2:0])
  `SVA_INV(a_core_bc_bus, c_bc_bus == m_w[9][3:3])
  `SVA_INV(a_core_host_addr, c_host_addr == m_w[10][10:0])
  `SVA_INV(a_core_host_wdata, c_host_wdata == m_w[11][15:0])
  `SVA_INV(a_core_bc_start, c_bc_start == m_pulse_CMD[0])
  `SVA_INV(a_core_host_wr, c_host_wr == m_pulse_CMD[1])
  `SVA_INV(a_core_host_rd, c_host_rd == m_pulse_CMD[2])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_bc == 1'h0 && c_cfg_bcast_en == 1'h1 && c_cfg_rt_addr == 5'h0 && c_cfg_sr == 1'h0 && c_cfg_busy == 1'h0 && c_cfg_ssf == 1'h0 && c_cfg_tf == 1'h0 && c_cfg_half == 8'h19 && c_cfg_resp_timeout == 8'h1C && c_cfg_vector == 16'h0 && c_cfg_bit_word == 16'h0 && c_bc_cmd1 == 16'h0 && c_bc_cmd2 == 16'h0 && c_bc_type == 3'h0 && c_bc_bus == 1'h0 && c_host_addr == 11'h0 && c_host_wdata == 16'h0 && c_bc_start == 1'h0 && c_host_wr == 1'h0 && c_host_rd == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_TIMING, m_rd && m_map && m_idx == 6)
  `FC(wr_TIMING, m_wr && m_map && m_idx == 6)
  `FC(rd_WORDS, m_rd && m_map && m_idx == 7)
  `FC(wr_WORDS, m_wr && m_map && m_idx == 7)
  `FC(rd_BC_CMD, m_rd && m_map && m_idx == 8)
  `FC(wr_BC_CMD, m_wr && m_map && m_idx == 8)
  `FC(rd_BC_CTRL, m_rd && m_map && m_idx == 9)
  `FC(wr_BC_CTRL, m_wr && m_map && m_idx == 9)
  `FC(rd_MEM_ADDR, m_rd && m_map && m_idx == 10)
  `FC(wr_MEM_ADDR, m_wr && m_map && m_idx == 10)
  `FC(rd_MEM_WDATA, m_rd && m_map && m_idx == 11)
  `FC(wr_MEM_WDATA, m_wr && m_map && m_idx == 11)
  `FC(rd_CMD, m_rd && m_map && m_idx == 12)
  `FC(wr_CMD, m_wr && m_map && m_idx == 12)
  `FC(rd_MEM_RDATA, m_rd && m_map && m_idx == 13)
  `FC(wr_MEM_RDATA, m_wr && m_map && m_idx == 13)
  `FC(rd_BC_STATUS, m_rd && m_map && m_idx == 14)
  `FC(wr_BC_STATUS, m_wr && m_map && m_idx == 14)
  `FC(rd_BC_STAT, m_rd && m_map && m_idx == 15)
  `FC(wr_BC_STAT, m_wr && m_map && m_idx == 15)
  `FC(rd_RT_STATUS, m_rd && m_map && m_idx == 16)
  `FC(wr_RT_STATUS, m_wr && m_map && m_idx == 16)
  `FC(rd_RT_MSG, m_rd && m_map && m_idx == 17)
  `FC(wr_RT_MSG, m_wr && m_map && m_idx == 17)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_BC_DONE_set, m_set[0])
  `FC(irq_BC_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_BC_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_BC_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_SYNC_set, m_set[1])
  `FC(irq_SYNC_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_SYNC_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_SYNC_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_SELF_TEST_set, m_set[2])
  `FC(irq_SELF_TEST_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_SELF_TEST_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_SELF_TEST_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_RT_RESET_set, m_set[3])
  `FC(irq_RT_RESET_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_RT_RESET_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_RT_RESET_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_SYNC_DATA_set, m_set[4])
  `FC(irq_SYNC_DATA_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_SYNC_DATA_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_SYNC_DATA_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_RT_MSG_AVAIL_set, m_set[5])
  `FC(irq_RT_MSG_AVAIL_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_RT_MSG_AVAIL_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_RT_MSG_AVAIL_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_RT_MSG_OVF_set, m_set[6])
  `FC(irq_RT_MSG_OVF_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_RT_MSG_OVF_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_RT_MSG_OVF_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(cmd_bc_start, m_pulse_CMD[0])
  `FC(cmd_host_wr, m_pulse_CMD[1])
  `FC(cmd_host_rd, m_pulse_CMD[2])
  `FC(RT_MSG_capture, c_rt_msg && !m_state_RT_MSG)
  `FC(RT_MSG_overflow, c_rt_msg && m_state_RT_MSG && !(m_rd && m_map && m_idx == 17))
  `FC(RT_MSG_pop, m_rd && m_map && m_idx == 17 && m_state_RT_MSG)
  `FC(RT_MSG_read_empty, m_rd && m_map && m_idx == 17 && !m_state_RT_MSG)
  `FC(RT_MSG_pop_and_capture, c_rt_msg && m_state_RT_MSG && m_rd && m_map && m_idx == 17)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind MIL_STD_1553_apb MIL_STD_1553_apb_sva u_apb_sva (.*);
